/**
 * The sandbox platform's SQLite schema.
 *
 * Kept next to the sandbox code rather than in `src/db/sqlite-schema.ts` so the
 * platform owns its own tables: the session and memory tables are the product's
 * data model, these are the execution platform's. `sqlite-schema.ts` appends this
 * block to the base schema and bumps `PRAGMA user_version`, which is how an
 * existing database on disk gets the new tables without a destructive rewrite.
 *
 * Rules that hold across every table:
 *
 *   - ids are TEXT opaque values generated by the application;
 *   - timestamps are ISO-8601 TEXT in UTC;
 *   - arrays and JSON are TEXT, parsed at the store boundary;
 *   - `execution_events`, `permission_decisions` and `audit_events` are
 *     append-only: no UPDATE paths are exposed for them;
 *   - an execution's idempotency key is unique *per sandbox*, which is what makes
 *     a duplicated tool call a lookup rather than a second side effect;
 *   - a permission request's `request_key` is unique among *open* requests, which
 *     is what stops a retry from opening a second approval.
 *
 * Version history:
 *
 *   2 — execution platform tables (ADR 017/018)
 *   3 — `sandboxes.resource_profile`
 *   4 — permission modes, requests, human approvals, decisions, grants
 *       (ADR 020); `sandboxes.config_digest` so a mode change rebuilds a
 *       container whose mount no longer matches the policy.
 *   5 — task-scoped working directory (ADR 021): `sandbox_tasks.workspace_root`,
 *       `current_cwd`, `cwd_version`, `cwd_invalidated_at`, `cwd_invalid_reason`,
 *       `executions.cwd_version`, and `task_cwd_operations` for idempotent
 *       retries.
 */

export const SANDBOX_SCHEMA_VERSION = 5;

/**
 * Task working directory (ADR 021).
 *
 * `cwd_version` is the compare-and-set token: the conditional `UPDATE` in
 * `compareAndSetTaskCwd` matches on it, so two concurrent changes cannot both
 * win and a stale retry is detectable rather than silently overwriting.
 *
 * `task_cwd_operations` is the idempotency record for one `change_directory`
 * call. It stores the whole result, because a retry must return the original
 * answer — not recompute it against a directory that has since moved.
 */
export const CWD_SCHEMA = `
CREATE TABLE IF NOT EXISTS task_cwd_operations (
  operation_id TEXT PRIMARY KEY,
  task_id      TEXT NOT NULL,
  path         TEXT NOT NULL,
  result       TEXT NOT NULL,
  cwd_version  INTEGER NOT NULL,
  created_at   TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS task_cwd_operations_task_idx
  ON task_cwd_operations (task_id, created_at DESC);
`;

/**
 * Tables and indexes new in version 4.
 *
 * Split out because a version-3 database needs `CREATE TABLE` for these but must
 * not re-create the version-2/3 tables; `SANDBOX_SCHEMA` interpolates the same
 * block so a fresh file and an upgraded file converge.
 */
export const PERMISSION_SCHEMA = `
CREATE TABLE IF NOT EXISTS permission_policies (
  policy_id     TEXT PRIMARY KEY,
  scope_type    TEXT NOT NULL CHECK (scope_type IN ('organization', 'project', 'session', 'task', 'sandbox')),
  scope_id      TEXT NOT NULL,
  version       INTEGER NOT NULL,
  mode          TEXT NOT NULL CHECK (mode IN ('read-only', 'auto', 'on-request', 'restricted')),
  configuration TEXT NOT NULL DEFAULT '{}',
  expires_at    TEXT,
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL,
  UNIQUE (scope_type, scope_id, version)
);

CREATE INDEX IF NOT EXISTS permission_policies_scope_idx
  ON permission_policies (scope_type, scope_id, version DESC);

CREATE TABLE IF NOT EXISTS permission_requests (
  request_id               TEXT PRIMARY KEY,
  request_key              TEXT NOT NULL,
  organization_id          TEXT NOT NULL,
  project_id               TEXT NOT NULL,
  session_id               TEXT NOT NULL,
  task_id                  TEXT NOT NULL,
  sandbox_id               TEXT,
  execution_id             TEXT,
  mode                     TEXT NOT NULL,
  principal_type           TEXT NOT NULL,
  principal_id             TEXT NOT NULL,
  action                   TEXT NOT NULL,
  tool_name                TEXT NOT NULL,
  resource_type            TEXT NOT NULL,
  resource_identifier      TEXT NOT NULL,
  resource_scope           TEXT NOT NULL DEFAULT '[]',
  status                   TEXT NOT NULL,
  reason                   TEXT NOT NULL DEFAULT '',
  risk_level               TEXT NOT NULL DEFAULT 'low',
  permission_policy_version TEXT NOT NULL,
  decision_id              TEXT,
  grant_id                 TEXT,
  approval_request_id      TEXT,
  auto_review              TEXT,
  expires_at               TEXT NOT NULL,
  created_at               TEXT NOT NULL,
  updated_at               TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS permission_requests_task_idx
  ON permission_requests (task_id, created_at DESC);
CREATE INDEX IF NOT EXISTS permission_requests_key_idx
  ON permission_requests (request_key, status);
CREATE INDEX IF NOT EXISTS permission_requests_status_idx
  ON permission_requests (status, expires_at);

CREATE TABLE IF NOT EXISTS permission_approval_requests (
  approval_request_id TEXT PRIMARY KEY,
  request_id          TEXT NOT NULL REFERENCES permission_requests(request_id) ON DELETE CASCADE,
  task_id             TEXT NOT NULL,
  session_id          TEXT NOT NULL,
  sandbox_id          TEXT,
  scope               TEXT NOT NULL CHECK (scope IN ('once', 'task', 'session')),
  status              TEXT NOT NULL,
  requested_by        TEXT NOT NULL,
  decided_by          TEXT,
  decision_reason     TEXT,
  expires_at          TEXT NOT NULL,
  decided_at          TEXT,
  created_at          TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS permission_approvals_task_idx
  ON permission_approval_requests (task_id, created_at DESC);
CREATE INDEX IF NOT EXISTS permission_approvals_status_idx
  ON permission_approval_requests (status, expires_at);

CREATE TABLE IF NOT EXISTS permission_decisions (
  decision_id               TEXT PRIMARY KEY,
  request_id                TEXT NOT NULL,
  task_id                   TEXT NOT NULL,
  session_id                TEXT NOT NULL,
  sandbox_id                TEXT,
  effect                    TEXT NOT NULL,
  layer                     TEXT NOT NULL,
  mode                      TEXT NOT NULL,
  permission_policy_version TEXT NOT NULL,
  reason                    TEXT NOT NULL,
  created_at                TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS permission_decisions_task_idx
  ON permission_decisions (task_id, created_at DESC);
`;

export const SANDBOX_SCHEMA = `
CREATE TABLE IF NOT EXISTS sandbox_tasks (
  task_id      TEXT PRIMARY KEY,
  session_id   TEXT NOT NULL,
  user_id      TEXT NOT NULL,
  status       TEXT NOT NULL CHECK (status IN ('ACTIVE', 'PAUSED', 'COMPLETED', 'FAILED', 'ARCHIVED')),
  workspace_id TEXT NOT NULL,
  sandbox_id   TEXT,
  workspace_root TEXT,
  current_cwd  TEXT,
  cwd_version  INTEGER NOT NULL DEFAULT 1,
  cwd_invalidated_at TEXT,
  cwd_invalid_reason TEXT,
  created_at   TEXT NOT NULL,
  updated_at   TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS sandbox_tasks_session_idx ON sandbox_tasks (session_id);
CREATE INDEX IF NOT EXISTS sandbox_tasks_user_idx    ON sandbox_tasks (user_id, updated_at DESC);

CREATE TABLE IF NOT EXISTS sandbox_workspaces (
  workspace_id     TEXT PRIMARY KEY,
  task_id          TEXT NOT NULL REFERENCES sandbox_tasks(task_id) ON DELETE CASCADE,
  storage_location TEXT NOT NULL,
  mode             TEXT NOT NULL CHECK (mode IN ('bind', 'copy')),
  current_version  TEXT NOT NULL,
  created_at       TEXT NOT NULL,
  updated_at       TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS sandbox_workspaces_task_idx ON sandbox_workspaces (task_id);

CREATE TABLE IF NOT EXISTS sandbox_workspace_checkpoints (
  checkpoint_id       TEXT PRIMARY KEY,
  workspace_id        TEXT NOT NULL REFERENCES sandbox_workspaces(workspace_id) ON DELETE CASCADE,
  task_id             TEXT NOT NULL,
  created_at          TEXT NOT NULL,
  source_execution_id TEXT,
  content_digest      TEXT NOT NULL,
  storage_location    TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS sandbox_checkpoints_workspace_idx
  ON sandbox_workspace_checkpoints (workspace_id, created_at DESC);

CREATE TABLE IF NOT EXISTS sandboxes (
  sandbox_id        TEXT PRIMARY KEY,
  task_id           TEXT NOT NULL REFERENCES sandbox_tasks(task_id) ON DELETE CASCADE,
  runtime_type      TEXT NOT NULL,
  runtime_id        TEXT NOT NULL,
  image_digest      TEXT NOT NULL,
  workspace_id      TEXT NOT NULL REFERENCES sandbox_workspaces(workspace_id) ON DELETE RESTRICT,
  policy_version    TEXT NOT NULL,
  resource_profile  TEXT NOT NULL DEFAULT 'default',
  config_digest     TEXT NOT NULL DEFAULT '',
  status            TEXT NOT NULL,
  created_at        TEXT NOT NULL,
  last_heartbeat_at TEXT,
  updated_at        TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS sandboxes_task_idx   ON sandboxes (task_id, created_at DESC);
CREATE INDEX IF NOT EXISTS sandboxes_status_idx ON sandboxes (status);

CREATE TABLE IF NOT EXISTS executions (
  execution_id    TEXT PRIMARY KEY,
  task_id         TEXT NOT NULL,
  sandbox_id      TEXT NOT NULL REFERENCES sandboxes(sandbox_id) ON DELETE CASCADE,
  idempotency_key TEXT NOT NULL,
  command_digest  TEXT NOT NULL,
  command_json    TEXT NOT NULL,
  cwd             TEXT NOT NULL,
  cwd_version     INTEGER NOT NULL DEFAULT 1,
  status          TEXT NOT NULL,
  exit_code       INTEGER,
  started_at      TEXT,
  finished_at     TEXT,
  stdout          TEXT NOT NULL DEFAULT '',
  stderr          TEXT NOT NULL DEFAULT '',
  policy_version  TEXT NOT NULL,
  tool_call_id    TEXT,
  decision_id     TEXT,
  permission_mode TEXT,
  permission_policy_version TEXT,
  created_at      TEXT NOT NULL,
  updated_at      TEXT NOT NULL,
  UNIQUE (sandbox_id, idempotency_key)
);

CREATE INDEX IF NOT EXISTS executions_sandbox_idx ON executions (sandbox_id, created_at DESC);
CREATE INDEX IF NOT EXISTS executions_open_idx    ON executions (status);

CREATE TABLE IF NOT EXISTS execution_events (
  event_id        TEXT PRIMARY KEY,
  task_id         TEXT NOT NULL,
  sandbox_id      TEXT NOT NULL,
  execution_id    TEXT NOT NULL,
  idempotency_key TEXT NOT NULL,
  event_type      TEXT NOT NULL,
  timestamp       TEXT NOT NULL,
  policy_version  TEXT NOT NULL,
  payload         TEXT NOT NULL DEFAULT '{}'
);

CREATE INDEX IF NOT EXISTS execution_events_execution_idx
  ON execution_events (execution_id, timestamp);
CREATE INDEX IF NOT EXISTS execution_events_sandbox_idx
  ON execution_events (sandbox_id, timestamp DESC);

CREATE TABLE IF NOT EXISTS sandbox_approvals (
  approval_id    TEXT PRIMARY KEY,
  task_id        TEXT NOT NULL,
  action         TEXT NOT NULL,
  resource_scope TEXT NOT NULL,
  expires_at     TEXT NOT NULL,
  approved_by    TEXT NOT NULL,
  policy_version TEXT NOT NULL,
  created_at     TEXT NOT NULL,
  revoked_at     TEXT,
  grant_id       TEXT,
  organization_id TEXT,
  project_id     TEXT,
  session_id     TEXT,
  sandbox_id     TEXT,
  principal_id   TEXT,
  source         TEXT NOT NULL DEFAULT 'human_approval',
  status         TEXT NOT NULL DEFAULT 'active',
  scope_level    TEXT NOT NULL DEFAULT 'task',
  request_id     TEXT,
  approval_request_id TEXT,
  used_at        TEXT
);

CREATE INDEX IF NOT EXISTS sandbox_approvals_task_idx ON sandbox_approvals (task_id, expires_at);

CREATE TABLE IF NOT EXISTS sandbox_policies (
  policy_id     TEXT PRIMARY KEY,
  version       TEXT NOT NULL UNIQUE,
  scope         TEXT NOT NULL,
  configuration TEXT NOT NULL,
  created_at    TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS sandbox_audit_events (
  id             TEXT PRIMARY KEY,
  timestamp      TEXT NOT NULL,
  session_id     TEXT,
  task_id        TEXT,
  sandbox_id     TEXT,
  execution_id   TEXT,
  tool_call_id   TEXT,
  policy_version TEXT,
  approval_id    TEXT,
  action         TEXT NOT NULL,
  outcome        TEXT NOT NULL,
  detail         TEXT NOT NULL DEFAULT '{}'
);

CREATE INDEX IF NOT EXISTS sandbox_audit_time_idx ON sandbox_audit_events (timestamp DESC);
CREATE INDEX IF NOT EXISTS sandbox_audit_task_idx ON sandbox_audit_events (task_id, timestamp DESC);
CREATE INDEX IF NOT EXISTS sandbox_audit_execution_idx ON sandbox_audit_events (execution_id);

${PERMISSION_SCHEMA}
${CWD_SCHEMA}
`;
